ee:variables.ee:set-variable:
%dw 2.0
output application/java
import * from dw::core::Strings
fun first(v) = if (v is Array) (v[0] default null) else v
var q = attributes.queryParams default vars.rawQueryParams default {}
var groupingNumberRaw = first(q.groupingNumber default q['groupingNumber'] default null)
var nameRaw = first(q.name default q['name'] default null)
var commercialNameRaw = first(q.commercialName default q['commercialName'] default null)
var profile = upper((Mule::p('pagination.profile') default "Bajo") as String)
var maxLimit = if (profile == "ALTO") ((Mule::p('pagination.profiles.alto.max') default 100) as Number)
	else if (profile == "MEDIO") ((Mule::p('pagination.profiles.medio.max') default 50) as Number)
	else ((Mule::p('pagination.profiles.bajo.max') default 25) as Number)
var defaultLimit = maxLimit
var defaultOffset = (Mule::p('pagination.default.offset') default 0) as Number
var reqLimit = (first(q.limit default q.LIMIT default defaultLimit) default defaultLimit) as Number
var reqOffset = (first(q.offset default q.OFFSET default defaultOffset) default defaultOffset) as Number
var safeLimit = if (reqLimit > maxLimit) maxLimit else if (reqLimit < 0) 0 else reqLimit
var safeOffset = if (reqOffset < 0) 0 else reqOffset
---
{
	groupingNumber: if (groupingNumberRaw != null and !isBlank((groupingNumberRaw as String) default "")) (groupingNumberRaw as Number) else null,
	name: if (nameRaw != null and !isBlank((nameRaw as String) default "")) (nameRaw as String) else null,
	commercialName: if (commercialNameRaw != null and !isBlank((commercialNameRaw as String) default "")) (commercialNameRaw as String) else null,
	limit: safeLimit,
	offset: safeOffset,
	maxLimit: maxLimit
}

%dw 2.0
output application/java
var qp = vars.queryParameters default {}
---
{
	(numAgrupacion: qp.groupingNumber) if (qp.groupingNumber != null),
	(nombre: qp.name) if (qp.name != null),
	(nombreComercial: qp.commercialName) if (qp.commercialName != null)
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	status: 500,
	code: "COMMERCIAL_OFFER_QUERY",
	message: {
		message: "Error while querying commercial offer from mongo-sapi."
	},
	messageServer: "",
	cause: [{
		origin: app.name,
		message: (error.description default error.errorMessage.payload default "Unexpected error") as String
	}]
}

%dw 2.0
output application/json
---
{
	status: 400,
	code: "BAD_REQUEST",
	message: {
		message: "At least one filter is required: groupingNumber, name or commercialName."
	},
	messageServer: "",
	cause: [{
		origin: app.name,
		message: "Missing required query filter"
	}]
}
